package com.tekwatt.support.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="maintenance_jobs")public class MaintenanceJob{@Id private UUID id;@Column(nullable=false,unique=true,length=40)private String jobNumber;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,length=180)private String title;@Column(columnDefinition="TEXT")private String description;@Column(nullable=false,length=40)private String type;private UUID stationId;private UUID chargerId;private UUID technicianId;@Column(length=120)private String technicianName;@Column(nullable=false)private Instant scheduledAt;@Column(nullable=false,length=30)private String status;@Column(nullable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;protected MaintenanceJob(){}public MaintenanceJob(UUID t,String title,String d,String type,UUID station,UUID charger,UUID tech,String techName,Instant scheduled){id=UUID.randomUUID();jobNumber="MJ-"+Instant.now().toEpochMilli();tenantId=t;this.title=title;description=d;this.type=type;stationId=station;chargerId=charger;technicianId=tech;technicianName=techName;scheduledAt=scheduled;status="SCHEDULED";createdAt=Instant.now();updatedAt=createdAt;}public void status(String s){status=s;updatedAt=Instant.now();}public UUID getId(){return id;}public String getJobNumber(){return jobNumber;}public UUID getTenantId(){return tenantId;}public String getTitle(){return title;}public String getDescription(){return description;}public String getType(){return type;}public UUID getStationId(){return stationId;}public UUID getChargerId(){return chargerId;}public UUID getTechnicianId(){return technicianId;}public String getTechnicianName(){return technicianName;}public Instant getScheduledAt(){return scheduledAt;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
